CREATE TABLE `Order` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, `supplier` VARCHAR(191) NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Product` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(191) NOT NULL, `serialNumber` VARCHAR(191) NOT NULL, `type` VARCHAR(191) NOT NULL, `status` VARCHAR(191) NOT NULL, `price` DECIMAL(12,2) NOT NULL, `currency` VARCHAR(191) NOT NULL, `warrantyUntil` DATETIME(3) NOT NULL, `orderId` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Product_serialNumber_key`(`serialNumber`), INDEX `Product_orderId_idx`(`orderId`), PRIMARY KEY (`id`));
CREATE TABLE `Group` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(191) NOT NULL, `description` VARCHAR(191) NOT NULL, UNIQUE INDEX `Group_name_key`(`name`), PRIMARY KEY (`id`));
CREATE TABLE `User` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `role` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `User_email_key`(`email`), PRIMARY KEY (`id`));
ALTER TABLE `Product` ADD CONSTRAINT `Product_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
